/** the Wind dataset selector's ⓘ and the Help section "Wind datasets" text is dataset-agnostic:
 *  the datasets, grids and period come from the dataset table; the reanalysis facts are examples */
export const DATASET_INFO_TEXT = `The Wind dataset selector switches between wind datasets (${Object.values(DATASET_INFO).map((d) => `${d.name}, ${d.resolution}, ${d.period}`).join("; ")}).${datasetKindsText() ? ` ${datasetKindsText()}.` : ""}${datasetNotes().map((t) => ` ${t}`).join("")} The wind and sand-flux layers and the cell panel follow the selection; the dune-field mask, aridity and vegetation layers are the same for every dataset.`;

